    26  static bool check_buffer(RBuffer *b) {
    27          int i;
    28          ut8 ch;
    29          if (r_buf_read_at (b, 0, &ch, 1) != 1) {
    30                  return false;
    31          }
    32          if (ch != 0x80 && ch != 0x82) {
    33                  return false;
    34          }
    35          ut64 length = 0;
    36          const ut8 *buf = r_buf_data (b, &length);
    37          ut16 rec_size = ut8p_bw (buf + 1);
    38          ut8 str_size = *(buf + 3);
    39          if (str_size + 2 != rec_size || length < rec_size + 3) {
    40                  return false;
    41          }
    42          // check that the string is ASCII
    43          for (i = 4; i < str_size + 4; ++i) {
    44                  if (buf[i] > 0x7f) {
    45                          return false;
    46                  }
    47          }
    48          return r_bin_checksum_omf_ok (buf, length);
    49  }
    50  static bool check_bytes(const ut8 *buf, ut64 length) {
    51          int i;
    52          if (!buf || length < 4) {
    53                  return false;
    54          }
    55          if ((*buf != 0x80 && *buf != 0x82) || length < 4) {
    56                  return false;
    57          }
    58          ut16 rec_size = ut8p_bw (buf + 1);
    59          ut8 str_size = *(buf + 3);
    60          if (str_size + 2 != rec_size || length < rec_size + 3) {
    61                  return false;
    62          }
    63          // check that the string is ASCII
